const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
let homeComposition='b',navigationMode='guided';
let locale='uk',path='/',cart=[],attempt=null,receipt=null,submission=null,recovery=null,removed=null,storageOK=true,busy=false;
