const MARKER_KEY='nfc-v35-attempt-opaque-v1';
if(app)try{recovery=parseRecoveryMarker(localStorage.getItem(MARKER_KEY));}catch{storageOK=false;}
const publicCopy={formIntro:['Перевірте конфігурації та додайте контактні дані. Увесь кошик буде збережено як одну заявку.','Check the configurations and add your contact details. The whole cart is saved as one enquiry.','Sprawdź konfiguracje i podaj dane kontaktowe. Cały koszyk zostanie zapisany jako jedno zgłoszenie.'],contactBody:['Оберіть запит дизайну, консультацію або пропозицію на email.','Choose a design enquiry, consultation or proposal by email.','Wybierz zapytanie o projekt, konsultację lub ofertę na email.'],receiptEyebrow:['Заявку збережено','Enquiry saved','Zgłoszenie zapisane'],receiptBody:['Сервер підтвердив збереження однієї заявки. Це не оплата й не підтвердження відправлення повідомлення.','The server confirmed that one enquiry is saved. This does not confirm payment or notification delivery.','Serwer potwierdził zapis jednego zgłoszenia. Nie jest to potwierdzenie płatności ani dostarczenia powiadomienia.'],receiptReference:['Номер заявки','Enquiry reference','Numer zgłoszenia']};
const productionCopy={faq3a:['Ні. Кошик формує запит, а не платіж. Стандартна доставка Новою поштою по Україні безкоштовна; інші напрямки узгоджуємо окремо. Передоплата 200 UAH один раз після погодження входить у вартість карток.','No. The cart creates a request, not a payment. Standard Nova Poshta delivery within Ukraine is free; other destinations are agreed separately. The UAH 200 deposit is paid once after agreement and included in the card total.','Nie. Koszyk tworzy zapytanie, a nie płatność. Dostawę z Ukrainy do Polski opłaca odbiorca; koszt i przewoźnika uzgadniamy przed zaliczką. Zaliczka 20 PLN raz po uzgodnieniu jest wliczona w cenę kart.']};
const ownerWords={legacyMini:['Готова Mini-картка','Ready Mini card','Gotowa karta Mini'],selectProductPrompt:['Оберіть тип картки','Choose a card type','Wybierz typ karty'],selectDesignProduct:['Тип картки для вашого дизайну','Card type for your design','Typ karty do własnego projektu'],designContextNote:['Збережемо обраний тип разом із запитом на дизайн. Виготовлення погодимо окремо.','Your selected card type stays with the design enquiry. Production is agreed separately.','Wybrany typ karty zapiszemy wraz z zapytaniem o projekt. Produkcję uzgodnimy osobno.'],designRequest:['Зробити свій дизайн','Create your own design','Stwórz własny projekt'],branded:['Власний дизайн','Own design','Własny projekt']};
const t=k=>!reviewEnabled()&&productionCopy[k]?localized(productionCopy[k]):ownerWords[k]?localized(ownerWords[k]):publicCopy[k]?localized(publicCopy[k]):translate(k,locale),copy=p=>productCopy(typeof p==='string'?p:p.id,locale),market=()=>locale==='pl'?'PL':'UA';
const url=(p='/')=>BASE+(locale==='uk'?'':`/${locale}`)+(p.startsWith('/')?p:`/${p}`);
const money=(n,currency=market()==='PL'?'PLN':'UAH')=>new Intl.NumberFormat({uk:'uk-UA',en:'en-GB',pl:'pl-PL'}[locale],{maximumFractionDigits:0}).format(n)+' '+currency;
const product=id=>catalog.find(p=>p.id===id);
