function configError(form,errors){const box=form.querySelector('#config-error,.line-error');box.hidden=false;box.tabIndex=-1;if(!box.id)box.id='line-error-'+uid();box.textContent=[...new Set(errors.map(e=>errorText(e.code)))].join(' ');box.focus();for(const e of errors){const field=form.elements[e.field];field?.setAttribute('aria-invalid','true');field?.setAttribute('aria-describedby',box.id);}}
function snapshotContact(form){const f=new FormData(form);contact={name:String(f.get('name')||''),email:String(f.get('email')||''),phone:String(f.get('phone')||''),preferredMethod:String(f.get('preferredMethod')||'email'),messenger:String(f.get('messenger')||'')};consent=f.get('consent')==='on';serviceNotes=String(f.get('serviceNotes')||'');serviceDraft={...brandSnapshot(f),destination:f.has('serviceDestination')?String(f.get('serviceDestination')||''):serviceDraft.destination||''};}
async function submitAttempt(){
 if(!attempt||busy)return;busy=true;submission=null;render();const result=await sendAttempt(attempt);busy=false;submission=result;
 if(result.status==='success'&&await validReceipt(attempt,result.receipt)){
  receipt=result.receipt;attempt=null;clearMarker();submission=null;formErrors=[];contact={name:'',email:'',phone:'',preferredMethod:'email',messenger:''};consent=false;serviceDraft={};
  if(receipt.acceptedRequest.kind==='physical_order'){cart=[];persistCart();}navigate(url('/thank-you/'));
 }else{if(result.status==='success')submission={status:'timeout',code:'receipt_mismatch',retryable:true};if([400,413,422].includes(result.httpStatus)&&result.challengeRejectedBeforeWrite!==true){attempt=null;clearMarker();formErrors=[{field:'contact',code:result.code||'validation_failed'}];}render();document.querySelector('#submission-status')?.focus();}
}
